        local function contextBossProfile(j)
            return V[string.lower(j or "")] or E
        end
        local V, E =
            {
                red = Vector3.new(-144, 23, 268),
                green = Vector3.new(-159, 23, 335),
                yellow = Vector3.new(-105, 23, 377),
            }, {}
        local function contextBobCrystal(U)
            U = string.lower(U or "")
            local pos = E[U]
            if pos and os.clock() - pos.at < 5 then
                return pos.pos
            end
            pos = nil
            local secondBossCrystals = workspace:FindFirstChild("secondBossCrystals", true)
            if secondBossCrystals then
                for index, descendant in ipairs(secondBossCrystals:GetDescendants()) do
                    if descendant:IsA("BasePart") and string.lower(descendant.Name):find(U, 1, true) then
                        pos = descendant.Position
                        break
                    end
                end
            else
            end
            pos = pos or V[U]
            E[U] = {
                at = os.clock(),
                pos = pos,
            }
            return pos
        end
        local function contextBobCrystalCentroid()
            local U, J = Vector3.zero, 0
            for entry in pairs(V) do
                local V = contextBobCrystal(entry)
                if V then
                    U, J = U + V, J + 1
                else
                end
            end
            return J > 0 and U / J or nil
        end
        local runtimeState = {
            farmEnabled = true,
            destroyed = false,
            movementState = "starting",
            tickMs = 0,
            moveBoost = false,
            lastQ = -math.huge,
            lastE = -math.huge,
            lastClick = -math.huge,
        }
        local function contextLog(J, w)
            if runtimeState.bugLog then
                pcall(runtimeState.bugLog, J, w)
