        local function normalizeItemName(itemName)
            return (
                string
                    .lower(tostring(itemName or ""))
                    :gsub("\226\128\153", "'")
                    :gsub("\226\128\152", "'")
                    :gsub("\226\128\147", "-")
                    :gsub("\226\128\148", "-")
                    :gsub("%s+", " ")
                    :gsub("^%s+", "")
                    :gsub("%s+$", "")
            )
        end
        local armorAliases, armorLookupCache = {}, {}
        do
            local _ = {}
            local function addArmorAlias(aliasName, profileName)
                aliasName = normalizeItemName(aliasName)
                local entry = profilesByName[profileName]
                if aliasName == "" or _[aliasName] or not entry or not entry.a then
                    return
                end
                _[aliasName] = true
                armorAliases[#armorAliases + 1] = {
                    alias = aliasName,
                    entry = entry,
                }
            end
            for key, entry2 in pairs(profilesByName) do
                if entry2.a then
                    addArmorAlias(key, key)
                end
            end
            for index, entry3 in ipairs(profileAliases) do
                addArmorAlias(entry3[1], entry3[2])
            end
            addArmorAlias("crystalline guardian", "crystalline guadian")
            addArmorAlias("rogue guardian", "rouge guardian")
            addArmorAlias("rogue", "rouge")
            table.sort(armorAliases, function(O, _)
                if #O.alias ~= #_.alias then
                    return #O.alias > #_.alias
                end
                return O.alias < _.alias
            end)
        end
        local function findGearProfile(itemName, itemType)
            if itemType == "ability" then
                return nil
            end
            local c = normalizeItemName(itemName)
            if c == "" then
                return nil
            end
            if profilesByName[c] then
                return profilesByName[c]
            end
            if itemType ~= "chest" and itemType ~= "helmet" then
                return nil
            end
            if armorLookupCache[c] ~= nil then
                return armorLookupCache[c] or nil
            end
            for index2, entry in ipairs(armorAliases) do
                if c:find(entry.alias, 1, true) then
                    armorLookupCache[c] = entry.entry
                    return entry.entry
                end
            end
            armorLookupCache[c] = false
            return nil
        end
        gearProfiles.entryFor = findGearProfile
        local rarityRanks = {
            common = 1,
            uncommon = 2,
            rare = 3,
            epic = 4,
        }
        gearProfiles.maxPotential = function(S, D)
            local P, _ = math.max(0, math.floor(tonumber(D) or 0)), (math.floor(S + 0.5))
            while P > 0 and _ < 200 do
                _ += math.clamp(math.floor(_ / 20), 1, 10)
                P = P - 1
            end
            return if P > 0 then _ + P * 10 else _
        end
        local function validatedMaxPotential(statValue, remainingUpgrades)
            statValue = tonumber(statValue)
            if not statValue or statValue ~= statValue or math.abs(statValue) == math.huge then
                return nil
            end
            return gearProfiles.maxPotential(statValue, remainingUpgrades)
        end
        local function selectStatRange(P, _, l, c)
            local u = P.t
            if not u or #u == 0 then
                return nil
            end
            P = rarityRanks[string.lower(tostring(_ or ""))]
            if P and u[P] then
                return u[P]
            end
            P, _ = nil
            for index2, entry in ipairs(u) do
                index2 = if c > 0 and entry[2] > 0
                    then if c >= entry[1] and c <= entry[2]
                        then -1000000000
                        else 0 + math.min(math.abs(c - entry[1]), math.abs(c - entry[2]))
                    else 0
                index2 = if l > 0
                    then if l >= entry[5] and l <= entry[6]
                        then index2 - 1000000000
                        else if l < entry[5] then index2 + entry[5] - l else index2 + l - entry[6]
                    else index2
                if not P or index2 < P then
                    P, _ = index2, entry
                else
                end
            end
            return _
        end
        gearProfiles.primaryKey = function(L, P)
            local _, l, c, u =
                tonumber(L.physicalDamage or L.physicalPower),
                tonumber(L.spellPower),
                tonumber(L.health),
                findGearProfile(L.name, P)
            L = string.lower(u and u.c or "")
            if L:find("guardian") and c then
                return "health"
            end
            if L:find("mage") and l then
                return "spellPower"
            end
            if P == "weapon" and L:find("war") and _ then
                return "physicalDamage"
            end
            if P == "weapon" and _ and l then
                return _ >= l and "physicalDamage" or "spellPower"
            end
            if _ and l and math.max(_, l) >= 200 and math.max(_, l) > math.min(_, l) * 5 then
                return _ > l and "physicalDamage" or "spellPower"
            end
            return c and "health" or _ and "physicalDamage" or l and "spellPower" or nil
        end
        local function getPrimaryStat(P, _)
            local l = gearProfiles.primaryKey(P, _)
            if l == "health" then
                return tonumber(P.health)
            end
            if l == "spellPower" then
                return tonumber(P.spellPower)
            end
            if l then
                return tonumber(P.physicalDamage or P.physicalPower)
            end
            return nil
        end
        gearProfiles.compute = function(P, _)
            if type(P) ~= "table" then
                return nil
            end
            local l = findGearProfile(P.name, _)
            if not l then
                return nil
            end
            local O = getPrimaryStat(P, _)
            if not O then
                return nil
            end
            local L, c = tonumber(P.currentUpgrade) or 0, tonumber(P.maxUpgrades) or 0
            _ = validatedMaxPotential(O, math.max(0, c - L))
            if not _ then
                return nil
            end
            L = selectStatRange(l, P.rarity, _, c)
            if not L then
                return nil
            end
            c, l = tonumber(L[5]), tonumber(L[6])
            if not c or not l then
                return nil
            end
            L = l > c and (_ - c) / (l - c) * 100 or (_ >= l and 100 or 0)
            return math.floor(math.clamp(L, 0, 100) * 10 + 0.5) / 10
        end
        local inventoryTables = {}
        local lastInventoryScan = -1000000000
        local function scanInventoryTables(D)
            local P = type(getgc) ~= "function"
                or os.clock() - lastInventoryScan < (tonumber(context.CFG.godpotRescan) or 8)
            if P then
                return
            end
            lastInventoryScan = os.clock()
            table.clear(inventoryTables)
            local d, O = {
                D,
            }, game:GetService("Players").LocalPlayer
            P = O and (O:FindFirstChild("PlayerGui"))
            D = P and (P:FindFirstChild("inventory"))
            O = D and (D:FindFirstChild("mainBackground"))
            D = O and (O:FindFirstChild("innerBackground"))
            P, O = D and (D:FindFirstChild("rightSideFrame")), {}
            if P and (P:FindFirstChild("ScrollingFrame")) then
                O[#O + 1] = P.ScrollingFrame
            end
            if D and (D:FindFirstChild("leftSideFrame")) then
                O[#O + 1] = D.leftSideFrame
            end
            P = {}
            for index2, entry in ipairs(O) do
                for index3, child in ipairs(entry:GetChildren()) do
                    D, index3 = child:FindFirstChild("itemType"), child:FindFirstChild("uniqueItemNum", true)
                    child = D and tostring(D.Value)
                    if
                        index3
                        and child
                        and not P[child]
                        and (child == "weapon" or child == "chest" or child == "helmet" or child == "ability")
                    then
                        P[child] = true
                        d[#d + 1] = child .. "_" .. tostring(index3.Value)
                    end
                end
            end
            for index4, entry4 in ipairs(getgc(true)) do
                if type(entry4) == "table" then
                    for index5, entry5 in ipairs(d) do
                        D = rawget(entry4, entry5)
                        if type(D) == "table" and rawget(D, "UniqueItemID") then
                            inventoryTables[#inventoryTables + 1] = entry4
                            break
                        end
                    end
                end
            end
        end
        gearProfiles.gearFor = function(d, O, D, P)
            if type(getgc) ~= "function" or not d or d == "none" then
                return nil
            end
            local _ = d .. "_" .. tostring(O)
            for index2 = 1, 2, 1 do
                for index3, entry in ipairs(inventoryTables) do
                    index3 = rawget(entry, _)
                    if type(index3) == "table" and (not D or D == "" or tostring(index3.imageId) == D) then
                        return index3
                    end
                    if P and D then
                        for key2, entry4 in pairs(entry) do
                            if
                                type(key2) == "string"
                                and key2:sub(1, #d + 1) == d .. "_"
                                and type(entry4) == "table"
                                and entry4.equipped == true
                                and tostring(entry4.imageId) == D
                            then
                                return entry4
                            end
                        end
                    end
                end
                if index2 == 1 then
                    scanInventoryTables(_)
                end
            end
            return nil
        end
        gearProfiles.forItem = function(d, L, O, S)
            local D = gearProfiles.gearFor(d, L, O, S)
            return D and gearProfiles.compute(D, d) or nil
        end
        gearProfiles.color = function(d)
            if d >= 99 then
                return Color3.fromRGB(155, 255, 220)
            end
            if d >= 90 then
                return Color3.fromRGB(105, 235, 135)
            end
            if d >= 75 then
                return Color3.fromRGB(190, 230, 105)
            end
            if d >= 50 then
                return Color3.fromRGB(255, 220, 105)
            end
            if d >= 25 then
                return Color3.fromRGB(255, 166, 90)
            end
            return Color3.fromRGB(255, 110, 120)
        end
    end

    components.movementBoost = function(context)
        local config, runtimeState = context.CFG, context.RT
        local localPlayer, speedSettings =
            context.LocalPlayer, {
                TargetSpeed = 24,
                MinSpeed = 18,
                MaxSpeed = 26,
                FallbackSpeed = 16,
            }
        local character = localPlayer.Character
        local humanoid, boostEnabled, originalWalkSpeed, moverHeading =
            character and (character:FindFirstChildOfClass("Humanoid")), false
        local function ensureCharacter()
            local u = character and character.Parent and humanoid and humanoid.Parent
            if u then
                return true
            end
            character = localPlayer.Character
            humanoid = character and character:FindFirstChildOfClass("Humanoid")
            u = humanoid
            return u ~= nil
        end
        local function setMoverHeading(moverHeading2)
            moverHeading = moverHeading2
            runtimeState.moverHeading = moverHeading2
        end
        local targetSpeed = speedSettings.TargetSpeed
        local function enableSpeedBoost(R)
            local y = not ensureCharacter()
            if y then
                local q = targetSpeed
                return q
            end
            local q, locomotionSpeed =
                math.clamp(
                    tonumber(R) or speedSettings.TargetSpeed,
                    speedSettings.MinSpeed,
                    speedSettings.MaxSpeed
                ),
                boostEnabled
            if locomotionSpeed then
                R = math.abs(q - targetSpeed) >= 2
                if R then
                    targetSpeed = q
                end
                y = humanoid.WalkSpeed ~= targetSpeed
                if y then
                    humanoid.WalkSpeed = targetSpeed
                end
                runtimeState.locomotionSpeed = targetSpeed
                local y = targetSpeed
                return y
            end
            boostEnabled, targetSpeed = true, q
            originalWalkSpeed = humanoid.WalkSpeed > 0 and humanoid.WalkSpeed or nil
            humanoid.WalkSpeed = targetSpeed
            locomotionSpeed = nil
            locomotionSpeed, runtimeState.locomotion = targetSpeed, true
            runtimeState.locomotionSpeed = locomotionSpeed
            R = targetSpeed
            return R
        end
        local function disableSpeedBoost()
            moverHeading = nil
            runtimeState.moverHeading = nil
            local y = boostEnabled
            if not y then
                return
            end
            boostEnabled = false
            runtimeState.locomotion = false
            runtimeState.locomotionSpeed = nil
            y = ensureCharacter()
            if y then
                local humanoid2 = humanoid
                humanoid2.WalkSpeed = originalWalkSpeed or speedSettings.FallbackSpeed
            end
            originalWalkSpeed = nil
        end
        local characterAddedConnection = localPlayer.CharacterAdded:Connect(function(newCharacter)
            character = newCharacter
            humanoid, boostEnabled, originalWalkSpeed, moverHeading =
                newCharacter:FindFirstChildOfClass("Humanoid"), false, nil, nil
            runtimeState.moverHeading = nil
            runtimeState.locomotion = false
            runtimeState.locomotionSpeed = nil
        end)
        local function stopSpeedBoost()
            disableSpeedBoost()
            local connection = characterAddedConnection
            if connection then
                characterAddedConnection:Disconnect()
                characterAddedConnection = nil
            end
        end
        context.LC = {
            on = enableSpeedBoost,
            off = disableSpeedBoost,
            steer = setMoverHeading,
            stop = stopSpeedBoost,
            CONFIG = speedSettings,
            active = function()
                return false
            end,
            boosted = function()
                local d = boostEnabled
                return d
