                        hazardReader.considerQueue[#hazardReader.considerQueue + 1] = y
                    end
                end
            )
            hazardReader.connections[#hazardReader.connections + 1] = localPlayer.CharacterAdded:Connect(
                function()
                    hazardReader.charAt = os.clock()
                    task.spawn(function()
                        local character = localPlayer.Character
                        local humanoid = character and (character:WaitForChild("Humanoid", 8))
                        if not humanoid then
                            return
                        end
                        local now = os.clock()
                        local u, connection = humanoid.Health
                        connection = humanoid.HealthChanged:Connect(function(P)
                            local q = u - 0.5
                            if P < q then
                                local runtimeState2 = context.RT
                                if runtimeState2 then
                                    runtimeState2.hurtAges = runtimeState2.hurtAges or {}
                                    runtimeState2.hurtAges[#runtimeState2.hurtAges + 1] = os.clock() - now
                                    if #runtimeState2.hurtAges > 30 then
                                        table.remove(runtimeState2.hurtAges, 1)
                                    end
                                end
                                if connection then
                                    connection:Disconnect()
                                end
                            end
                            u = P
                        end)
                    end)
                    if
                        hazardReader.firstWpKey ~= nil
                        and config.waypointFirstOnly ~= false
                        and not hazardReader.wpFlowDone
                    then
                        hazardReader.wpFlowDone = true
                        contextLogT(
                            "waypoint",
                            1,
                            "Reader",
                            "died after the first set: the waypoint flow is off for the rest of the run"
                        )
                    end
                    local bigRoom, lastDeathPos = hazardReader.bigRoom, hazardReader.lastDeathPos
                    if bigRoom and lastDeathPos then
                        local u, y = lastDeathPos.X - bigRoom.x, lastDeathPos.Z - bigRoom.z
                        if
                            u * u + y * y
                                <= ((bigRoom.r or 120) + (config.resetRoomLeave or 150)) ^ 2
                            and not bigRoom.resetWasUs
                        then
                            bigRoom.left = nil
                            bigRoom.resetDone = false
                            bigRoom.clearSince = nil
                            hazardReader.resetUsed = nil
                            hazardReader.catchUpUsed = nil
                            contextLogT(
                                "reset",
                                1,
                                "Reader",
                                "died inside the big room: its reset is armed again"
                            )
                            local diedInAt = hazardReader.charAt
                            bigRoom.diedInAt = diedInAt
                            hazardReader.spawnCp = nil
                            task.spawn(function()
                                local u, order = math.huge
                                for index = 1, 10, 1 do
                                    task.wait(0.3)
                                    if hazardReader.charAt ~= diedInAt then
                                        return
                                    end
                                    index = localPlayer.Character
                                    local h, dungeon =
                                        index and (index:FindFirstChild("HumanoidRootPart")),
                                        workspace:FindFirstChild("dungeon")
                                    if h and dungeon then
                                        for index2, child in ipairs(dungeon:GetChildren()) do
                                            index, index2 =
                                                child:FindFirstChild("checkPoint"), child:FindFirstChild("order")
                                            child = index2 and tonumber(index2.Value)
                                            if index and index:IsA("BasePart") and child then
                                                index2 = (index.Position - h.Position).Magnitude
                                                if index2 < u then
                                                    u, order = index2, child
                                                else
                                                end
                                            else
                                            end
                                        end
                                    else
                                    end
                                end
                                if
                                    hazardReader.charAt == diedInAt
                                    and order
                                    and u < (config.resetCatchUpSpawnR or 30)
                                then
                                    hazardReader.spawnCp = {
                                        at = diedInAt,
                                        order = order,
                                    }
                                end
                            end)
                        end
                    end
                    if bigRoom then
                        bigRoom.resetWasUs = false
                    end
                end
            )
            local remotes = replicatedStorage:FindFirstChild("remotes")
            for index3, entry2 in ipairs(remotes and remotes:GetChildren() or {}) do
                if entry2:IsA("RemoteEvent") and entry2.Name:find("BossSpecficEvents", 1, true) then
                    hazardReader.connections[#hazardReader.connections + 1] = entry2.OnClientEvent:Connect(
                        function(S, P)
                            if type(S) == "string" and S:find("^First Boss") and context.firstBossDead() then
                                return
                            end
                            context.famSeen(S)
                            local u = F[S]
                            if u then
                                local success, y = pcall(u, P)
                                if not success then
                                    contextLogT("evt", 2, "Reader", tostring(S) .. ": " .. tostring(y))
                                end
                            end
                        end
                    )
                end
            end
            pcall(function()
                local S = require(replicatedStorage:WaitForChild("Utility", 5):WaitForChild("BridgeNet2", 5))
                local P = S.ReferenceIdentifier("action")
                hazardReader.connections[#hazardReader.connections + 1] = S.ReferenceBridge("precastHitbox")
                    :Connect(function(S)
                        if type(S) ~= "table" then
                            return
                        end
                        local from = os.clock()
                            + (S.delayUntilAttack or 0)
                            - (workspace:GetServerTimeNow() - (S.startTime or workspace:GetServerTimeNow()))
                        if S[P] == "Circle" and S.position then
                            contextAddZone({
                                name = "circle",
                                kind = "zone",
                                bubbleKeep = true,
                                cframe = CFrame.new(S.position),
                                size = Vector3.new((S.radius or 5) * 2, 12, (S.radius or 5) * 2),
                                round = true,
                                from = from,
                                untilAt = from + 0.45,
                                telegraphed = true,
                            })
                        elseif S.cframe and S.size then
                            contextAddZone({
                                name = "cube",
                                kind = "zone",
                                bubbleKeep = true,
                                cframe = S.cframe,
                                size = Vector3.new(S.size.X, max(S.size.Y, 12), S.size.Z),
                                from = from,
                                untilAt = from + 0.45,
                                telegraphed = true,
                            })
                        end
                    end)
            end)
            contextLog("Reader", "listening")
        end
        local function contextReaderStop()
            for index, connection in ipairs(hazardReader.connections) do
                pcall(connection.Disconnect, connection)
            end
            hazardReader.connections = {}
        end
        local function contextNearlyDead(l)
            if not l or not l.humanoid or l.humanoid.Health <= 0 then
                return false
            end
            local c = hazardReader.hitSize[l.model]
            if not c or #c < 2 then
                return false
            end
            local u = 0
            for index, entry in ipairs(c) do
                u = if entry > u then entry else u
            end
            return u > 0 and l.humanoid.Health <= u * 2.2
        end
        context.clearThreats = function(l)
            hazardReader.bossDownUntil = os.clock() + config.bossDownQuiet
            for key, model in pairs(hazardReader.models) do
                if model.touchConn then
                    pcall(function()
                        model.touchConn:Disconnect()
                    end)
                end
                if model.touchConns then
                    for index, touchConn in ipairs(model.touchConns) do
                        pcall(function()
                            touchConn:Disconnect()
                        end)
                    end
                end
            end
            table.clear(hazardReader.models)
            table.clear(hazardReader.parts)
            for index2 = #hazardReader.zones, 1, -1 do
                hazardReader.zones[index2] = nil
            end
            table.clear(hazardReader.walls)
            hazardReader.count = 0
            hazardReader.orbLead = nil
            hazardReader.orbNear = nil
            hazardReader.orbRayU = nil
            runtimeState.reflex = nil
            contextLogT("clear", 2, "Reader", "threats cleared: " .. tostring(l))
        end
        context.RD = hazardReader
        context.hazards = function(now, boxes)
            gilded.refreshSafe(hazardReader, now)
            return context.GE.filter(now, context.GY.append(context.GR.append(context.GC.append(gildedProjectiles.append(contextHazards(now, boxes), now), now), now), now))
        end
        context.readerTick = contextReaderTick
        context.readerStart = contextReaderStart
        context.readerStop = contextReaderStop
        context.gameClock = contextGameClock
        context.nearlyDead = contextNearlyDead
    end

    components.dangerGeometry = function(context)
        local config = context.CFG
        local runtimeState = context.RT
        local hazardReader = context.RD
        local workspace = game:GetService("Workspace")
        local contextHazards = context.hazards
        local sqrt = math.sqrt
        local abs = math.abs
        local max = math.max
        local min = math.min
        local infinity = math.huge
        local dangerGeometry = {
            target = nil,
            reason = "",
            dangerHere = 0,
            here0 = 0,
            now = 0,
            offsets = {},
            outer = {},
            cands = {},
            boxes = {},
            reach = 2,
            halfHeight = 5,
            feet = 3,
            approach = nil,
            heading = nil,
            headingAt = -infinity,
            evalStats = {},
        }
        local function contextDepthOf(zone, y, q, V, E)
            local p = q - zone.cy
            if abs(p) > zone.hy + E then
                if
                    not (
                        p > 0
                        and p <= zone.hy + E + (config.sinkSlack or 4)
                        and zone.hy <= 1.5
                        and (zone.r or max(zone.ha or 0, zone.hb or 0)) >= 3
                        and context.belowNL
                        and context.belowNL()
                    )
                then
                    return -infinity
                end
            end
            p, E = y - zone.cx, V - zone.cz
            if zone.r then
                V = sqrt(p * p + E * E)
                q = zone.r - V
                if zone.ring then
                    if p * zone.sx + E * zone.sz < 0 then
                        return -infinity
                    end
                    q = min(q, V - zone.ring)
                else
                end
                return q
            end
            V, y = abs(p * zone.ax + E * zone.az) - zone.ha, abs(p * zone.bx + E * zone.bz) - zone.hb
            if V <= 0 and y <= 0 then
                return -max(V, y)
            end
            return -sqrt(max(V, 0) ^ 2 + max(y, 0) ^ 2)
        end
        local function depthWeight(R, y, q)
            local V = R + y
            if V >= 0 then
                return 1
            end
            if -V < q then
                return 1 + V / q
            end
            return 0
        end
        local function contextDangerAt(y, q, V, E, p, j, U)
            local J, w, Y, v, M =
                p or dangerGeometry.reach,
                dangerGeometry.halfHeight,
                j or config.dodgeShoulder,
                dangerGeometry.now,
                dangerGeometry.boxes
            j, p = v + E, 0
            for index = 1, #M, 1 do
                local n = M[index]
                if not n.far and not (U and U(n)) then
                    index = nil
                    if n.moving then
                        if j <= n.untilAt and (n.ground or abs(q - n.oy) <= n.halfH + w) then
                            local U, f = n.offset + n.speed * max(j - n.pathStart, 0), n.endAlong
                            U = if f and U > f then f else U
                            local r, o = n.dx, n.dz
                            local A, k = y - (n.ox + r * U), V - (n.oz + o * U)
                            local U, x, a = A * r + k * o, n.r
                            if x then
                                f = -A * o + k * r
                                index, a = x - sqrt(U * U + f * f), abs(f) - x
                            else
                                local f = abs(U) - n.halfL
                                a = abs(-A * o + k * r) - n.halfW
                                index = if f <= 0 and a <= 0
                                    then -max(f, a)
                                    else -sqrt(max(f, 0) ^ 2 + max(a, 0) ^ 2)
                            end
                            p = if index + J < 0
                                    and not n.noLane
                                    and not n.laneFree
                                    and U > n.halfL
                                    and a <= J
                                    and U - n.halfL <= n.speed * min(
                                        max(n.untilAt - j, 0),
                                        n.horizon or config.laneHorizon
                                    )
                                    and p < config.pathLaneDanger
                                then config.pathLaneDanger
                                else p
                        else
                        end
                    else
                        local from, U = n.from, not n.exact and (n.telegraphed or n.from > v)
                        local f = U and max(n.lead or config.dodgeLead, dangerGeometry.leadFloor or 0)
                            or (dangerGeometry.leadFloor or 0)
                        index = if j >= from - f and j <= n.untilAt then contextDepthOf(n, y, q, V, w) else index
                    end
                    if index then
                        local _, U
                        if n.fullKeep and not dangerGeometry.redRelax then
                            _, U = dangerGeometry.reach or J, config.redOrbShoulder or 0.75
                        else
                            _, U = J, Y
                        end
                        if n.slim then
                            _, U =
                                (min(_, n.slim + (dangerGeometry.lag or 0) * config.slimLagShare)),
                                min(U, config.slimShoulder)
                        else
                        end
                        local f = index + _
                        f = if n.soft and E > config.softAfter
                            then (if n.weight
                                then (if f >= 0 then 1 else if -f < U then 1 + f / U else 0) * n.weight
                                else if f >= 0 then 1 else if -f < U then 1 + f / U else 0) * config.softFactor
                            else if n.weight
                                then (if f >= 0 then 1 else if -f < U then 1 + f / U else 0) * n.weight
                                else if f >= 0 then 1 else if -f < U then 1 + f / U else 0
                        if f > p then
                            if f >= 1 then
                                return 1
                            end
                            p = f
                        else
                        end
                    else
                    end
                else
                end
            end
            j = hazardReader.leash
            if j then
                q = j.enemy.root
                if q.Parent then
                    M = q.Position
                    if sqrt((y - M.X) ^ 2 + (V - M.Z) ^ 2) - j.radius > -4 then
                        return 1
                    end
                end
            end
            q = hazardReader.enemies
            for index2 = 1, #q, 1 do
                v = q[index2]
                if v.melee and not v.isBoss then
                    index2 = min(E, 0.6)
                    w, M =
                        sqrt((y - v.x - v.vx * index2) ^ 2 + (V - v.z - v.vz * index2) ^ 2),
                        v.extent + v.meleeDistance + 2
                    j = w <= M + J and 1
                        or depthWeight(-(w - M - config.meleeBuffer), J, Y * 2)
                            * config.meleeBandWeight
                    if j > p then
                        if j >= 1 then
                            return 1
                        end
                        p = j
                    else
                    end
                else
                end
            end
            return p
        end
        context.redOrbNear = function(O, P, _)
            local u, y, q, V, E, p, j, U =
                dangerGeometry.boxes or {},
                dangerGeometry.now or os.clock(),
                dangerGeometry.reach or 1.8,
                (config.redOrbStand or 0.5) + (_ or 0),
                config.redOrbStandStep or 0.2,
                O.X,
                O.Z,
                (P or 0) + 1.0E-6
            P = type(E) == "number" and E > 0
            for index = 1, #u, 1 do
                _ = u[index]
                if _.fullKeep and _.moving then
                    O = (_.r or _.halfW or 12) + q + V
                    local u, q, V, w, Y, endAlong, M, Z, n, f, r =
                        O * O,
                        (_.untilAt or 0) + 0.2,
                        _.offset or 0,
                        _.speed or 0,
                        _.pathStart or y,
                        _.endAlong,
                        _.ox,
                        _.oz,
                        _.dx,
                        _.dz,
                        0
                    while r <= U do
                        index = y + r
                        if index <= q then
                            local O = V + w * max(index - Y, 0)
                            O = if endAlong and O > endAlong then endAlong else O
                            local _, y = p - (M + n * O), j - (Z + f * O)
                            if _ * _ + y * y < u then
                                return true
                            end
                        elseif P then
                            break
                        end
                        r += E
                    end
                end
            end
            return false
        end
        local function contextWalkable(P, _, u, y, q)
            local V = config.maxStepHeight + 1.5
            local E = Vector3.new(P.X, P.Y - dangerGeometry.feet + V, P.Z)
            P = workspace:Blockcast(CFrame.new(E), Vector3.new(2.5, 3, 2.5), Vector3.new(_, u + V, y) - E, q)
            return P == nil, P
        end
        local function contextDecide(P, _)
            local now = os.clock()
            dangerGeometry.lag =
                min((runtimeState.pingS or 0) * max(runtimeState.speedNow or 16, 16), config.pingMarginMax)
            dangerGeometry.now, dangerGeometry.reach, dangerGeometry.halfHeight, dangerGeometry.feet =
                now,
                P.Size.X * 0.5 + config.dodgeMargin + dangerGeometry.lag,
                (_.HipHeight + P.Size.Y) * 0.5 + 2.5,
                _.HipHeight + P.Size.Y * 0.5
            dangerGeometry.halfWidth = P.Size.X * 0.5
            if context.carryIgnoresHits and context.carryIgnoresHits() then
                for index = #dangerGeometry.boxes, 1, -1 do
                    dangerGeometry.boxes[index] = nil
                end
            else
                contextHazards(now, dangerGeometry.boxes)
            end
            dangerGeometry.here0, dangerGeometry.dangerHere, dangerGeometry.target, dangerGeometry.reason, dangerGeometry.origin =
                0, 0, nil, "bubble", P.Position
            for index2 = #dangerGeometry.cands, 1, -1 do
                dangerGeometry.cands[index2] = nil
            end
            runtimeState.moveBoost = false
        end
        context.DG = dangerGeometry
        context.dangerAt = contextDangerAt
        context.decide = contextDecide
        context.walkable = contextWalkable
        context.depthOf = contextDepthOf
        context.RING_GAPS = { 31.25, 43.75, 56.25, 68.75, 81.25 }
        context.odinRankOff = function(L)
            local O, S, D, P =
                config.odinRankIn or 56.25,
                config.odinRankOut or 81.25,
                config.odinRank3In or 43.75,
                config.odinRank3Weight or 0.35
            if L >= O and L <= S then
                return 0
            end
            if L > S then
                return L - S
            end
            if L >= D then
                return (O - L) * P
            end
            return (O - D) * P + (D - L)
        end
        context.odinBandOff = function(d)
            local L, O = config.odinBandIn or 43.75, config.odinRankOut or 81.25
            if d < L then
                return L - d
            end
            if d > O then
                return d - O
            end
            return 0
        end
    end

    components.odinMechanics = function(context)
        local config = context.CFG
        local hazardReader = context.RD
        local workspace = game:GetService("Workspace")
        local sqrt = math.sqrt
        local floor = math.floor
        local abs = math.abs
        local infinity = math.huge
        local max = math.max
        local min, odinMechanics, setMetatable, weakKeys =
            math.min, {}, setmetatable, {
                __mode = "k",
            }
        odinMechanics.sets = setMetatable({}, weakKeys)
        odinMechanics.setList = {}
        odinMechanics.orbs = {}
        odinMechanics.orbList = {}
        odinMechanics.missiles = {}
        odinMechanics.missileList = {}
        odinMechanics.arrays = {}
        odinMechanics.lines = {}
        odinMechanics.lineList = {}
        odinMechanics.lastTick = 0
        context.OD = odinMechanics
        local function m(part)
            local y = max(part.Size.X, part.Size.Z) * 0.5
            if y < 10 then
                return nil
            end
            local q = part.CFrame.LookVector
            local V, E = q.X, q.Z
            q = sqrt(V * V + E * E)
            if q < 0.01 then
                return nil
            end
            V /= q
            E /= q
            q = part.Position
            return q.X - V * (y / 2),
                q.Z - E * (y / 2),
                y,
                y - (y >= 100 and (config.ringThicknessOuter or 17.5) or (config.ringThickness or 12.5)),
                V,
                E,
                q.Y
        end
        odinMechanics.noteRingSet = function(model, spawn)
            local q = odinMechanics.sets[model]
            if q then
                return q
            end
            q = {
                model = model,
                spawn = spawn,
                boxed = {},
                parts = {},
                bands = {},
                n = 0,
                centre = nil,
            }
            odinMechanics.sets[model] = q
            odinMechanics.setList[#odinMechanics.setList + 1] = q
            if context.logT then
                context.logT("rings", 2, "Odin", "ring set seen")
            end
            return q
        end
        local function R(y, madeAt)
            local V = config.ringLive or 1.3
            if not y.centreX then
                local E = y.model:FindFirstChild("center") or y.model:FindFirstChild("Center")
                if E and (E:IsA("BasePart")) then
                    y.centreX, y.centreZ = E.Position.X, E.Position.Z
                end
            end
            for index, child in ipairs(y.model:GetChildren()) do
                if child:IsA("BasePart") and not y.boxed[child] then
                    index = string.lower(child.Name)
                    if index == "ring" then
                        local j, centreZ, J, inner, Y, v, M = m(child)
                        if j and y.centreX then
                            local Z, n = child.Position.X - y.centreX, child.Position.Z - y.centreZ
                            local f = sqrt(Z * Z + n * n)
                            if f > 1 then
                                Y, v = Z / f, n / f
                            else
                            end
                            j, centreZ = y.centreX, y.centreZ
                        else
                            local arenaCentre = hazardReader.arenaCentre
                            j = if j
                                    and arenaCentre
                                    and abs(
                                            sqrt(
                                                (child.Position.X - arenaCentre.X) ^ 2
                                                    + (child.Position.Z - arenaCentre.Z) ^ 2
                                            ) - J / 2
                                        )
                                        > (config.ringPosTol or 4)
                                then nil
                                else j
                        end
                        if j then
                            y.boxed[child] = true
                            y.parts[#y.parts + 1] = child
                            y.bands[#y.bands + 1] = {
                                cx = j,
                                cz = centreZ,
                                R = J,
                                inner = inner,
                                sx = Y,
                                sz = v,
                            }
                            y.n = y.n + 1
                            if context.addZone then
                                context.addZone({
                                    name = "ring arc",
                                    kind = "zone",
                                    bubbleKeep = true,
                                    slim = config.ringSlim,
                                    tight = true,
                                    cframe = CFrame.new(j, M, centreZ),
                                    size = Vector3.new(
                                        (J + (config.ringPad or 0)) * 2,
                                        12,
                                        (J + (config.ringPad or 0)) * 2
                                    ),
                                    round = true,
                                    ring = inner - (config.ringPad or 0),
                                    sx = Y,
                                    sz = v,
                                    from = y.spawn,
                                    untilAt = y.spawn + V,
                                    exact = true,
                                    madeAt = madeAt,
                                    model = y.model,
                                })
                            end
                        end
                    elseif index == "center" then
                        y.boxed[child] = true
                        y.centre = child
                        local position, j = child.Position, max(child.Size.X, child.Size.Y, child.Size.Z)
                        y.centreR, y.centreX, y.centreZ = j * 0.5, position.X, position.Z
                        if context.addZone then
                            context.addZone({
                                name = "ring centre",
                                kind = "zone",
                                bubbleKeep = true,
                                cframe = CFrame.new(position.X, position.Y, position.Z),
                                size = Vector3.new(j, 12, j),
                                round = true,
                                from = y.spawn,
                                untilAt = y.spawn + V,
                                exact = true,
                                madeAt = madeAt,
                                model = y.model,
                            })
                        end
                    end
                end
            end
        end
        local function y(q)
            if config.ringInvulnFree == false or hazardReader.charAt == nil then
                return false
            end
            return q.spawn + (config.ringLive or 1.3)
                <= hazardReader.charAt
                    + (config.invulnAfterRespawn or 4)
                    - (config.ringInvulnMargin or 0.2)
        end
        local function q(V, E, p, j)
            if y(V) then
                return false
            end
            j = (j or 0) + (config.ringPad or 0)
            local bands = V.bands
            for index = 1, #bands, 1 do
                local zone = bands[index]
                local U, Y = E - zone.cx, p - zone.cz
                if U * zone.sx + Y * zone.sz >= -j then
                    index = sqrt(U * U + Y * Y)
                    if index >= zone.inner - j and index <= zone.R + j then
                        return true, zone.R
                    end
                end
            end
            if V.centreR then
                local U, J = E - V.centreX, p - V.centreZ
                if sqrt(U * U + J * J) <= V.centreR + j then
                    return true, 0
                end
            end
            return false
        end
        odinMechanics.ringClear = function(V, E, p)
