                local Z, n, f =
                    j - M.spawn,
                    (
                        config.odinAllLanes == false
                            and (not (config.odinCentralBeam ~= false and odinMechanics.central ~= nil) or M == odinMechanics.central)
                        or config.odinAllLanes ~= false
