            local n, f, r = (config.fieldOrbKeep or 10) + M, odinLanes(v), hazardReader.orbBlastAt
            local p = if Z
                then r ~= nil and abs(Y - r) < 0.5
                else r ~= nil and r - Y < (config.orbBlastLead or 2) + 0.3 and Y < r + 0.8
            p = if config.orbBlastOnContact ~= false then false else p
