                Z = odinMechanics.orbList[index]
                index = max(Y - Z.t, 0)
                local A, k, x, a, e, N = Z.x + Z.vx * index, Z.z + Z.vz * index, 0, f and f[Z.part]
                local f = k
                if a then
                    e, k = lanePos(a, Y - v)
                else
                    k = N
                end
                if e then
                    A = e
                else
                    N = E(Z)
                    if N and index > N then
