                config.bobOrbStep or 0.1
            for index = 1, #bobOrbs, 1 do
                n = bobOrbs[index]
                Z, index = n.x, n.z
                local f = sqrt((vector.X - Z) ^ 2 + (vector.Z - index) ^ 2)
                local F, vector2, g =
                    if f < a + 2 then f - 2 else a,
                    config.crystalShield ~= false
                            and n.homing
                            and n.colour
                            and context.bobCrystal
                            and context.bobCrystal(n.colour)
                        or nil,
                    (config.crystalShieldR or 6.5) ^ 2
                if F > 0 then
                    local a, i = F * F, N
                    while i <= x do
                        if vector2 and (Z - vector2.X) ^ 2 + (index - vector2.Z) ^ 2 < g then
                            break
