        local function fF(vector, vector2, vector3, kF, xF, aF, eF)
            local NF, IF, FF, CF, gF =
                math.atan2(xF, kF),
                math.rad((config.rodinKeepZoneDeg or 70) + 10),
                (config.rodinKeepMaxR or 88) ^ 2,
                infinity
            for index = 0, 35, 1 do
                kF = index / 36 * 2 * 3.141592653589793
                if abs((kF - NF + 3.141592653589793) % 6.283185307179586 - 3.141592653589793) >= IF then
                    xF, index = vector2.X + math.cos(kF) * aF, vector2.Z + math.sin(kF) * aF
                    if (xF - vector3.X) ^ 2 + (index - vector3.Z) ^ 2 <= FF then
                        local oF = sqrt((xF - vector.X) ^ 2 + (index - vector.Z) ^ 2)
                        if oF < CF then
                            CF, gF = oF, Vector3.new(xF, eF, index)
                        else
                        end
                    else
                    end
                else
                end
            end
            return gF or Vector3.new(vector.X, eF, vector.Z)
        end
        local function rF(oF, AF)
            local kF, xF = tostring(game.JobId) .. "|" .. tostring(AF) .. "|" .. tostring(oF), 5381
            for index = 1, #kF, 1 do
                xF = (xF * 33 + string.byte(kF, index)) % 4294967296
            end
            return xF
        end
        local function contextOrbRoleNow(AF, lot, xF, aF, eF)
            local orbRole = runtimeState.orbRole
