                return orbRole
            end
            if AF - (runtimeState.keepEvalAt or -infinity) > (config.rodinKeepForget or 10) then
                runtimeState.keepSeen = {}
            end
            runtimeState.keepEvalAt = AF
            local keepSeen = runtimeState.keepSeen
            local FF = config.rodinKeepSettle or 1
            local CF = config.rodinKeepMemory or 4
            local function orbRole2(iF, bF)
                local BF = keepSeen[iF]
                if ZF(bF, xF, aF, eF) then
                    if not BF then
