                        and index.Parent
                        and aF
                        and aF.Health > 0
                        and (not arenaCentre or a(index.Position, arenaCentre) <= (config.rodinKeepArenaR or 110))
                    then
                        iF += 1
                        if orbRole2(entry.UserId, index.Position) then
                            lot = rF(entry.UserId, eF)
                            bF = if not bF or lot < bF.lot
                                then {
                                    lot = lot,
                                }
                                else bF
                        else
                        end
                    else
                    end
                else
                end
            end
            orbRole2 = if iF == 0
                then {
                    keeper = true,
                    why = "alone in the arena",
                }
                else if bF and not (CF and rF(localPlayer.UserId, eF) < bF.lot)
