                and hazardReader.rodinFanAt
                and kF - hazardReader.rodinFanAt < (config.rodinFanFor or 5.5)
            then
                local kF, NF =
                    math.atan2(aF.Z - arenaCentre.Z, aF.X - arenaCentre.X),
                    sqrt((aF.X - arenaCentre.X) ^ 2 + (aF.Z - arenaCentre.Z) ^ 2)
                local IF = abs(
                    (
                        kF
                        - (rodinFanYaw + 0.3490658503988659 * math.floor(
                            (kF - rodinFanYaw) / 0.3490658503988659 + 0.5
