            end
            zF, iF = sqrt(bF * bF - NF * NF), config.rodinRailBossMin or 10
            local IF, FF, CF = abs(NF) < iF and sqrt(iF * iF - NF * NF) or 0, { -1, 1 }
            for index, entry in ipairs(FF) do
                NF, bF = eF + entry * IF, eF + entry * zF
                entry, index = min(NF, bF), max(NF, bF)
                iF = 0 < entry and entry or (0 > index and index or 0)
