                        Si, Li = arenaCentre.X - rodinFlamePlaced.x, arenaCentre.Z - rodinFlamePlaced.z
                        li = max(sqrt(Si * Si + Li * Li), 0.5)
                    else
                    end
                    Di, Pi = rodinFlamePlaced.x + Si / li * (Oi + 2), rodinFlamePlaced.z + Li / li * (Oi + 2)
                else
                end
            else
            end
            return Vector3.new(Di, di or 0, Pi)
        end
        local function di(vector, Li, Oi, Si, Di, vector2)
            local arenaCentre, li, ci =
                hazardReader.arenaCentre, ((config.rodinSweepArenaR or 100) - 4) ^ 2, hazardReader.rodinSweep
            local ui = config.touchLanesAsOne ~= false
                and ci ~= nil
                and ci.model ~= nil
                and ci.model.Parent ~= nil
                and not runtimeState.touchdownOn
            local hi, mi, Ri, yi, qi, Vi =
                ui and context.BB.blueBeamsLong and context.BB.blueBeamsLong(config.touchLaneHold or 4.4) or Oi,
                config.beamEscapeWays or 32,
                ui and (config.touchBeamFar or 60) or (config.beamEscapeFar or 40),
                {},
                {},
                context.BB.orbArrive and context.BB.orbArrive(vector.X, vector.Z, Oi) or 0
            local function spare(pi, ji, Ui)
                return contextDangerAt(pi, vector.Y, ji, Ui, 1, 0.5) < 0.5
                    and contextDangerAt(pi, vector.Y, ji, Ui + 0.6, 1, 0.5) < 0.5
                    and not contextSweepHotAt(pi, ji, Li + Ui + 0.5, Li)
            end
            for index = 0, mi - 1, 1 do
                ci = index * 2 * 3.141592653589793 / mi
                index, ui = math.cos(ci), math.sin(ci)
                local ji
                for index2 = 2, Ri, 2 do
                    local Ri, Ji = vector.X + index * index2, vector.Z + ui * index2
                    if arenaCentre and (Ri - arenaCentre.X) ^ 2 + (Ji - arenaCentre.Z) ^ 2 >= li then
                        break
                    end
                    local _i = index2 / Si
                    if not context.BB.onBlueBeam(Ri, Ji, 0.5, hi) then
                        if spare(Ri, Ji, _i) then
                            local cost = index2
                                + (
                                    vector2
                                        and (sqrt((vector2.X - Ri) ^ 2 + (vector2.Z - Ji) ^ 2) - a(
                                            vector,
                                            vector2
                                        )) * (config.blueBeamGoalW or 0.3)
                                    or 0
                                )
                            cost = if Di then cost + YF(Di, Ri, Ji) else cost
                            cost = if context.BB.yellowAt
                                    and context.BB.yellowAt(Ri, Ji, Li + _i, hi)
                                then cost + (config.rodinYellowCost or 1000)
                                else cost
                            local Li, Pi = #yi + 1, {}
                            Pi.q, Pi.d, Pi.cost, yi[Li] = Vector3.new(Ri, vector.Y, Ji), index2, cost, Pi
                            break
                        end
                    else
                        if context.BB.orbArrive then
                            local spare2 = context.BB.orbArrive(Ri, Ji, Oi) - _i
                            ji = if spare2 >= (config.beamThroughSpare or 0.8)
                                    and spare2 > Vi + 0.3
                                    and (not ji or spare2 > ji.spare)
                                    and spare(Ri, Ji, _i)
                                then {
                                    q = Vector3.new(Ri, vector.Y, Ji),
                                    d = index2,
                                    spare = spare2,
                                }
                                else ji
                        else
                        end
                    end
                end
                if ji then
                    qi[#qi + 1] = ji
                end
            end
            table.sort(yi, function(Li, Pi)
                return Li.cost < Pi.cost
            end)
            for index3 = 1, min(#yi, config.beamEscapeTry or 16), 1 do
                ci = yi[index3]
                if
                    not context.BB.pathTouchesRed(vector, ci.q, Si)
                    and context.BB.orbPathSafe(vector, ci.q, Si)
                then
                    return ci, "clear"
                end
            end
            table.sort(qi, function(Li, Pi)
                return Li.spare > Pi.spare
            end)
            for index4 = 1, min(#qi, config.beamThroughTry or 8), 1 do
                Di = qi[index4]
                if
                    not context.BB.pathTouchesRed(vector, Di.q, Si)
                    and context.BB.orbPathSafe(vector, Di.q, Si)
                then
                    return Di, "through"
                end
            end
            if config.beamEscapeForced ~= false then
                Di, mi = {
                    qi,
                    yi,
                }
                for index5, entry in ipairs(Di) do
                    for index6 = 1, #entry, 1 do
                        ui = entry[index6]
                        spare = ui.spare
                        spare = (
                            if not spare and context.BB.orbArrive
                                then context.BB.orbArrive(ui.q.X, ui.q.Z, Oi) - ui.d / Si
                                else spare
                        ) or 0
                        mi = if (not mi or spare > mi.spare)
                                and not context.BB.pathTouchesRed(vector, ui.q, Si)
                            then {
                                q = ui.q,
                                d = ui.d,
                                spare = spare,
                            }
                            else mi
                    end
                end
                if mi then
                    return mi, "forced"
                end
            end
            return nil
        end
        context.isSpiralBox = function(Qi)
            return Qi ~= nil and Qi.name == "bonusbosssmallspiralflame"
        end
        context.spiralArms = function(Qi, vector)
            local spiralArms = hazardReader.spiralArms
            if not spiralArms or spiralArms.rig ~= hazardReader.rodinRig then
                spiralArms = {
                    list = {},
                    n = 0,
                    rig = hazardReader.rodinRig,
                }
                hazardReader.spiralArms = spiralArms
            else
            end
            if spiralArms.at == Qi then
                return spiralArms.list
            end
            spiralArms.at = Qi
            local Si = {}
            for key, model in pairs(hazardReader.models) do
                if model.name == "bonusbosssmallspiralflame" and not model.spArm and key.Parent then
                    local Di = model.pc or model.hb
                    if Di and Di.Parent then
                        local position = Di.Position
                        local li, ci = position.X - vector.X, position.Z - vector.Z
                        Si[#Si + 1] = {
                            rec = model,
                            x = position.X,
                            z = position.Z,
                            rad = math.sqrt(li * li + ci * ci),
                            ang = math.atan2(ci, li),
                            r0 = math.max(Di.Size.Y, Di.Size.Z) * 0.5,
                            spawn = model.spawn or Qi,
                        }
                    end
                end
            end
            if #Si > 1 then
                table.sort(Si, function(Di, Pi)
                    if Di.spawn ~= Pi.spawn then
                        return Di.spawn < Pi.spawn
                    end
                    return Di.rad < Pi.rad
                end)
            end
            local Di, Pi = config.rodinArmLinkD or 24, config.rodinArmLinkT or 0.4
            for index, entry in ipairs(Si) do
                local Si, ci = Di
                for index2, entry2 in ipairs(spiralArms.list) do
                    index = entry2.head
                    index2 = entry.spawn - index.spawn
                    if index2 >= -0.05 and index2 <= Pi then
                        local ui = math.sqrt((entry.x - index.x) ^ 2 + (entry.z - index.z) ^ 2)
                        if ui <= Si then
                            Si, ci = ui, entry2
                        else
                        end
                    else
                    end
                end
                if ci then
                    Si = ci.head
                    local _i = entry.ang - Si.ang
                    entry.th = Si.th
                        + (
                            if _i > 3.141592653589793
                                then _i - 6.283185307179586
                                else if _i < -3.141592653589793 then _i + 6.283185307179586 else _i
                        )
                    if not ci.sign and math.abs(entry.th - ci.first.th) > 0.05 then
                        ci.sign = entry.th > ci.first.th and 1 or -1
                    end
                    if not ci.sign or (entry.th - Si.th) * ci.sign >= 0 then
                        ci.head = entry
                    end
                    ci.n = ci.n + 1
                else
                    entry.th = entry.ang
                    spiralArms.n = spiralArms.n + 1
                    ci = {
                        id = spiralArms.n,
                        first = entry,
                        head = entry,
                        n = 1,
                    }
                    spiralArms.list[#spiralArms.list + 1] = ci
                end
                entry.rec.spArm = ci.id
            end
            local Si, _i, li, ci, list =
                config.rodinSpiralLook or 2.5,
                config.rodinArmGrow or 3,
                config.rodinArmEndR or 108,
                config.rodinSpiralDet or 0.85,
                {}
            for index3, entry3 in ipairs(spiralArms.list) do
                Pi, index3 = entry3.head, entry3.first
                entry3.live = entry3.sign ~= nil
                    and Qi - Pi.spawn <= (config.rodinArmIdle or 0.35)
                    and Pi.rad < li - 2
                if Qi - Pi.spawn <= ci + 1.5 then
                    list[#list + 1] = entry3
                end
                Di = (Pi.th - index3.th) * (entry3.sign or 1)
                _i = Di > 1.5 and math.clamp((Pi.rad - index3.rad) / Di, 2, 4.5) or _i
                local Ri, pred = Di * (Pi.rad + index3.rad) * 0.5, Pi.spawn - index3.spawn
                entry3.b = _i
                entry3.s = entry3.n >= 8 and Ri > 20 and math.clamp(Ri / (entry3.n - 1), 7, 15)
                    or (config.rodinArmStep or 10.9)
                entry3.vp = pred > 0.4 and Ri > 20 and math.clamp(Ri / pred, 90, 260)
                    or (config.rodinArmSpeed or 165)
                pred = {}
                if entry3.live then
                    local rad, hi, spawn, qi = Pi.rad, Pi.th, Pi.spawn, entry3.s / entry3.vp
                    for index4 = 1, 400, 1 do
                        index4 = entry3.s / math.sqrt(rad * rad + _i * _i)
                        hi += entry3.sign * index4
                        rad += _i * index4
                        spawn += qi
                        if rad > li or spawn > Qi + Si then
                            break
                        end
                        if spawn + ci >= Qi - 0.05 then
                            pred[#pred + 1] = {
                                x = vector.X + rad * math.cos(hi),
                                z = vector.Z + rad * math.sin(hi),
                                r0 = Pi.r0,
                                det = spawn + ci,
                            }
                        end
                    end
                end
                entry3.pred = pred
            end
            spiralArms.list = list
            return list
        end
        context.spiralFront = function(Qi, Li)
            if not Qi.live then
                return nil
            end
            local Oi = (Li - Qi.head.th) * Qi.sign % 6.283185307179586
            Li = Qi.head.rad + (Qi.b or 3) * Oi
            if Li > (config.rodinArmEndR or 108) + (Qi.head.r0 or 8.5) then
                return nil
            end
            return Li
        end
        context.spiralList = function(Qi, Li)
            local spiralListCache = hazardReader.spiralListCache
            if spiralListCache and spiralListCache.at == Qi then
                local Si = spiralListCache.byM[Li]
                if Si then
                    return Si
                end
            else
                spiralListCache = nil
            end
            local Si, Di, Pi = {}, config.rodinSpiralDet or 0.85, config.rodinSpiralGone or 0.45
            for key, model in pairs(hazardReader.models) do
                if model.name == "bonusbosssmallspiralflame" then
                    local ci = model.pc or model.hb
                    if key.Parent and ci and ci.Parent and ci.Transparency < 0.9 then
                        local position, hi = ci.Position, math.max(ci.Size.Y, ci.Size.Z) * 0.5
                        model.spX, model.spZ = position.X, position.Z
                        model.spR0 = hi
                        local left = (model.spawn or Qi) + Di - Qi
                        if left >= -Pi or config.rodinSpiralKeepStale == true then
                            Si[#Si + 1] = {
                                x = position.X,
                                z = position.Z,
                                R = hi + Li,
                                r0 = hi,
                                left = left,
                                arm = model.spArm,
                            }
                        end
                    elseif model.spX and not key.Parent and config.rodinSpiralKeepGone ~= false then
                        local left2 = (model.spawn or Qi) + Di - Qi
                        if left2 >= -Pi then
                            Si[#Si + 1] = {
                                x = model.spX,
                                z = model.spZ,
                                R = model.spR0 + Li,
                                r0 = model.spR0,
                                left = left2,
                                arm = model.spArm,
                                ghost = true,
                            }
                        end
                    end
                end
            end
            Di = hazardReader.arenaCentre
            if
                config.rodinSpiralForecast == true
                and config.rodinSpiralArms ~= false
                and Di
                and hazardReader.rodinRig
                and hazardReader.rodinRig.Parent
            then
                for index, entry in ipairs(context.spiralArms(Qi, Di)) do
                    for index2, entry2 in ipairs(entry.pred) do
                        Si[#Si + 1] = {
                            x = entry2.x,
                            z = entry2.z,
                            R = entry2.r0 + Li,
                            r0 = entry2.r0,
                            left = entry2.det - Qi,
                            pred = true,
                            arm = entry.id,
                        }
                    end
                end
            end
            if not spiralListCache then
                spiralListCache = {
                    at = Qi,
                    byM = {},
                }
                hazardReader.spiralListCache = spiralListCache
            else
            end
            spiralListCache.byM[Li] = Si
            return Si
        end
        context.spiralWalkBad = function(Qi, vector, Oi, Si, Di, Pi, _i)
            local li, ci, ui, hi = math.max(Si or 28, 4), Di or 0, Oi.X - vector.X, Oi.Z - vector.Z
            Oi, Si, Di = math.sqrt(ui * ui + hi * hi), 0, 0
            if Oi > 0.01 then
                Si, Di = ui / Oi, hi / Oi
            else
            end
            local mi, Ri, yi, qi, Vi =
                Pi and (config.rodinSpiralSlackTight or 0.95) or (config.rodinSpiralSlack or 0.8),
                config.rodinSpiralGone or 0.45,
                config.rodinSpiralUnc or 0.3,
                dangerGeometry.reach or 1.8,
                0
            for index, entry in ipairs(Qi) do
                index, hi, ui =
                    Pi and (entry.r0 or entry.R) + qi + (config.rodinSpiralTight or 0.5) or entry.R,
                    vector.X - entry.x,
                    vector.Z - entry.z
                local Qi, Li = hi * Si + ui * Di, hi * hi + ui * ui - index * index
                index = Qi * Qi - Li
                if index > 0 then
                    Li = math.sqrt(index)
                    local Si, Di = math.max(-Qi - Li, 0), math.min(-Qi + Li, Oi)
                    if Si <= Di then
                        local Qi, Li =
                            Si <= 0 and 0 or ci + Si / li, Di >= Oi - 0.01 and math.huge or ci + Di / li
                        if
                            not (
                                if entry.pred
                                    then Li <= entry.left - yi or Qi >= entry.left + Ri + yi
                                    else Li <= math.max(entry.left, 0) * mi or Qi >= entry.left + Ri
                            )
                        then
                            Vi += 1
                            if _i and Vi >= _i then
                                return Vi
                            end
                        else
                        end
                    else
                    end
                else
                end
            end
            return Vi
        end
        context.missileHit = function(vector, vector2, Oi, Si)
            local Di, Pi, _i, li =
                (config.missileLaneHalf or 5) + (dangerGeometry.reach or 1.8) + (config.rodinHopMissilePad or 1),
                (config.missileHalfLen or 16) + (dangerGeometry.reach or 1.8),
                vector2.X - vector.X,
                vector2.Z - vector.Z
            local ci = math.sqrt(_i * _i + li * li)
            local ui, hi, mi = math.clamp(math.ceil(ci / 3), 1, 40), math.max(Oi or 28, 1), Si or 0
            for key, part in pairs(hazardReader.parts) do
                if key.Parent and string.lower(key.Name):find("thirdbossmissile", 1, true) then
                    Oi, Si = part.vx or 0, part.vz or 0
                    local yi = math.sqrt(Oi * Oi + Si * Si)
                    if yi > 2 then
                        local qi, Vi, Ei = Oi / yi, Si / yi, key.Position
                        for index = 0, ui, 1 do
                            local yi = index / ui
                            index = mi + ci * yi / hi
                            local ui, pi =
                                vector.X + _i * yi - (Ei.X + Oi * index), vector.Z + li * yi - (Ei.Z + Si * index)
                            if math.abs(ui * qi + pi * Vi) <= Pi and math.abs(-ui * Vi + pi * qi) <= Di then
                                return index
                            end
                        end
                        local Qi, _i =
                            vector2.X - (Ei.X + Oi * (mi + ci / hi)), vector2.Z - (Ei.Z + Si * (mi + ci / hi))
                        Ei = Qi * qi + _i * Vi
                        if math.abs(-Qi * Vi + _i * qi) <= Di and Ei > -Pi then
                            return mi + ci / hi
                        end
                    end
                end
            end
            return nil
        end
        context.missileClearIn = function(Qi, Li, Oi, Si)
            local Di, Pi = Si or 2, 0
            while Pi <= Di + 1.0E-6 do
                if not context.missileHit(Qi, Li, Oi, Pi) then
                    return Pi
                end
                Pi += 0.1
            end
            return nil
        end
        context.spiralRedOn = function(Qi, Li, Oi, Si)
            local Di = context.BB
            if not (Di and Di.pathTouchesRed) then
                return false
            end
            if
                not (hazardReader.rodinRig and hazardReader.rodinRig.Parent)
                or config.rodinSpiralTimedWalks == false
            then
                return Di.pathTouchesRed(Qi, Li, Oi)
            end
            if Di.pathTouchesRed(Qi, Li, Oi, context.isSpiralBox) then
                return true
            end
            Di = context.spiralList(
                Si or os.clock(),
                (dangerGeometry.reach or 1.8) + (config.rodinSpiralMargin or 2.5)
            )
            return context.spiralWalkBad(Di, Qi, Li, Oi, 0, false, 1) > 0
        end
        local function Qi(Li, Oi, Si, Di)
            local Pi, _i, li = dangerGeometry.reach or 1.8, config.orbBeamMargin or 1
            local ci = 0
            for index = 1, #Li, 1 do
                local hi = Li[index]
                if hi.orb == Oi then
                    local Li, Oi = Si - hi.ox, Di - hi.oz
                    local Si, Di = Li * hi.ux + Oi * hi.uz, hi.vw + Pi + _i
                    if Si > -Di and Si < (hi.dL or hi.L) + Di then
                        index = Li * hi.uz - Oi * hi.ux
                        local Li = abs(index) - (Di + (hi.cone and max(Si, 0) * hi.cone or 0))
                        if not li or Li < li then
                            li, ci = Li, index >= 0 and 1 or -1
                        else
                        end
                    else
                    end
                else
                end
            end
            return li, ci
        end
        context.spiralGuardApply = function(Li)
            if context.GS.ownsMovement(Li) then return end
            if
                config.rodinSpiralGuard == false
                or not (hazardReader.rodinRig and hazardReader.rodinRig.Parent)
                or not context.spiralList
            then
                return
            end
            if
                contextColourPinned(Li)
                or contextFanPinned(Li)
                or contextColourAttackLive(Li)
                or hazardReader.touchdown ~= nil
            then
                return
            end
            local Oi = hazardReader.rodinSplit
            if Oi and Oi.model and Oi.model.Parent and not Oi.over then
                return
            end
            if not (movement.cmdAt == Li and movement.cmdDir) then
                return
            end
            local Si, humanoid, Di = context.character()
            if not (humanoid and Di and humanoid.Health > 0) then
                return
            end
            local position, _i =
                Di.Position,
                context.spiralList(Li, (dangerGeometry.reach or 1.8) + (config.rodinSpiralMargin or 1.5))
            if #_i == 0 then
                return
            end
            if not GF(_i, position.X, position.Z, 0) then
                return
            end
            Di = movement.cmdDir
            Oi = sqrt(Di.X * Di.X + Di.Z * Di.Z)
            if Oi < 0.01 then
                return
            end
            local li, ci = config.burstMax or 28, config.rodinSpiralGuardAhead or 3
            if GF(_i, position.X + Di.X / Oi * ci, position.Z + Di.Z / Oi * ci, ci / li) then
                return
            end
            _i = combatBrain.goTo and Li - (combatBrain.goToAt or -infinity) < 0.5 and combatBrain.goTo
                or Vector3.new(position.X + Di.X / Oi * 30, position.Y, position.Z + Di.Z / Oi * 30)
            Di = context.spiralAround and context.spiralAround(position, Li, _i, li)
            if Di then
                Oi, ci = Di.X - position.X, Di.Z - position.Z
                _i = sqrt(Oi * Oi + ci * ci)
                if _i > 0.3 then
                    runtimeState.spiralGuardAt = Li
                    movement.cmdDir = Vector3.new(Oi / _i, 0, ci / _i)
                    movement.cmdAt = Li
                    movement.driving = true
                    N(false)
                    C(humanoid, true, li)
                    humanoid:Move(Vector3.new(Oi / _i, 0, ci / _i), false)
                    contextSetState(
                        "RODIN SPIRAL: the way on runs into the spiral - round it toward where it is going"
                    )
                    contextLogT(
                        "spiralguard",
                        1,
                        "Brain",
                        "the way on ran into the spiral - round it toward the goal"
                    )
                    return
                end
            end
            runtimeState.spiralGuardAt = Li
            movement.cmdDir = nil
            movement.cmdAt = Li
            movementBoost.steer(nil)
            humanoid:Move(Vector3.zero, false)
            movement.stallSince = nil
            movement.lastPos = nil
            runtimeState.stalledFor = 0
            movement.cornerUntil = nil
            movement.cornerDir = nil
            contextSetState("RODIN SPIRAL: the way on runs into the spiral - waiting outside it")
            contextLogT("spiralguard", 1, "Brain", "the way on ran into the spiral - held outside it")
        end
        context.inTouchCorner = function(Li, Oi, Si)
            local touchCorners = hazardReader.touchCorners
            if
                config.rodinTouchCorners == false
                or not touchCorners
                or (Si or os.clock()) - touchCorners.at > 0.5
            then
                return false
            end
            Si = config.rodinTouchCornerR or 30
            for index, pt in ipairs(touchCorners.pts) do
                if (Li - pt.x) ^ 2 + (Oi - pt.z) ^ 2 < Si * Si then
                    return true
                end
            end
            return false
        end
        context.spiralWayDanger = function(vector, vector2, Si, Di, Pi, _i)
            local li, isSpiralBox, ui, hi =
                max(Si or 28, 4),
                context.isSpiralBox,
                config.rodinSpiralExitDanger or 0.5,
                sqrt((vector2.X - vector.X) ^ 2 + (vector2.Z - vector.Z) ^ 2)
            local Si, mi =
                hi / li, if context.BB.pathTouchesRed(vector, vector2, li, isSpiralBox) then 1000 else 0
            mi = if context.BB.orbPathSafe and not context.BB.orbPathSafe(vector, vector2, li)
                then mi + 1000
                else mi
            mi = if Pi and context.spiralWalkBad
                then mi + 100 * context.spiralWalkBad(Pi, vector, vector2, li, 0, true)
                else mi
            mi = if contextDangerAt(vector2.X, vector.Y, vector2.Z, Si, nil, nil, isSpiralBox) > ui
                then mi + 50
                else mi
            mi = if contextSweepHotAt(vector2.X, vector2.Z, Di + Si + 1, Di) then mi + 50 else mi
            mi = if _i
                then if not context.spiralMissileOK(vector, vector2, li, Di) then mi + 50 else mi
                else if context.missileLaneAt(vector2.X, vector2.Z, Di) then mi + 50 else mi
            mi = if context.redOrbNear
                    and context.redOrbNear(vector2, Si + (config.rodinSpiralOrbStay or 1))
                then mi + 50
                else mi
            mi = if not _i and context.missileLaneCross(vector, vector2, Di) then mi + 20 else mi
            mi = if context.BB.yellowAt and context.BB.yellowAt(vector2.X, vector2.Z, Di + Si)
                then mi + 20
                else mi
            Di = math.clamp(math.ceil(hi / 3), 1, 20)
            for index = 1, Di - 1, 1 do
                _i = index / Di
                if
                    contextDangerAt(
                        vector.X + (vector2.X - vector.X) * _i,
                        vector.Y,
                        vector.Z + (vector2.Z - vector.Z) * _i,
                        Si * _i,
                        nil,
                        nil,
                        isSpiralBox
                    ) > ui
                then
                    mi += 20
                    break
                end
            end
