            local ui, hi = a(vector, vector2), config.burstMax or 28
            ci = config.castRootTime or 0.7
            local mi = ci + (config.rodinAggroStay or 0.8)
            local function Ri(yi)
                local qi = 0
                if context.attackReady then
                    local Vi, Ei = context.attackReady()
                    qi = if not Vi then Ei or 0 else qi
                else
                end
                local Vi = 0
                if context.buffState and config.attackNeedsBuffUp ~= false then
