            local N = runtimeState.bobCyc
            if not (N and N.start) then
                return false
            end
            local zF = config.bobRound or 14.9
            if N.periods and #N.periods > 0 then
                local WF = {}
                for index = 1, #N.periods, 1 do
                    WF[index] = N.periods[index]
                end
                table.sort(WF)
                zF = WF[math.floor((#WF + 1) / 2)]
            else
            end
            local WF = (y or os.clock()) - N.start
            if WF < 0 or WF > zF * 3 then
                return false
            end
            N, y = WF % zF, config.bobSpreadAt or 8.5
            return N >= y - (config.bobOutBefore or 2.6) and N <= y + (config.bobOutAfter or 1.2)
        end
