            end
            if config.bobClose ~= false then
                return max(
                    min(context.bobHitEdge(y) - (config.bobAggroSpare or 5), config.bobStandD or 45),
                    (config.bobCloseKeepOut or 30) + (config.bobAggroKeepIn or 4)
                )
            end
            return max(
                context.bobHitEdge(y) - (config.bobAggroSpare or 5),
                (config.bobKeepOutRadius or 68) + (config.bobAggroKeepIn or 4)
            )
        end
        context.bobCycleTick = function(bobCyc)
