                if not bobCyc.circleT or spikeT.t - bobCyc.circleT > (config.bobChainGap or 2) then
                    local start = spikeT.chainAt or spikeT.t
                    if bobCyc.start and start - bobCyc.start > 10 and start - bobCyc.start < 20 then
                        bobCyc.periods[#bobCyc.periods + 1] = start - bobCyc.start
                        if #bobCyc.periods > 8 then
                            table.remove(bobCyc.periods, 1)
                        end
                    end
                    bobCyc.start = start
                    bobCyc.spikeSeen = false
                end
                bobCyc.circleT = spikeT.t
            end
            spikeT = hazardReader.lastSpikesAt
            if spikeT and spikeT ~= bobCyc.spikeT then
                bobCyc.spikeT = spikeT
                if
