                    and not bobCyc.spikeSeen
                    and spikeT - bobCyc.start > 2.5
                    and spikeT - bobCyc.start < 7
                then
                    bobCyc.spikes[#bobCyc.spikes + 1] = spikeT - bobCyc.start
                    if #bobCyc.spikes > 8 then
                        table.remove(bobCyc.spikes, 1)
                    end
                    bobCyc.spikeSeen = true
                end
            end
            return bobCyc
        end
