        context.circleLaneExit = function(side, vector)
            local circleChain = hazardReader.circleChain
            if
                config.bobChainExit == false
                or not circleChain
                or side - (circleChain.lastAt or -infinity) > (config.bobChainLive or 1.6)
            then
                runtimeState.circleExit = nil
                return nil
            end
            local WF, Qi = circleChain.dx, circleChain.dz
            local Li, Oi, Si = -Qi, vector.X - circleChain.ox, vector.Z - circleChain.oz
            local Di, Pi, _i, li, ci =
                Oi * WF + Si * Qi, Oi * Li + Si * WF, (dangerGeometry.reach or 2.8) + (config.bobChainPad or 6), 0
            for index = 0, (config.bobChainN or 10) - 1, 1 do
                Si, Oi =
                    ((circleChain.size0 or 22) + (circleChain.gr or 6) * index) * 0.5 + _i,
                    Di - (circleChain.sp or 22) * index
                if abs(Oi) < Si then
                    local hi = sqrt(Si * Si - Oi * Oi)
                    if hi > li then
                        li, ci = hi, index
                    else
                    end
                else
                end
            end
            if li <= 0 or abs(Pi) >= li then
                Si = runtimeState.circleExit
                if Si and Si.chainAt == circleChain.chainAt and config.bobChainReCheck ~= false then
                    Si.started = nil
                end
                return nil
            end
            local circleExit, ui =
                runtimeState.circleExit,
                (circleChain.chainAt or side)
                    + (circleChain.dt or 0.26) * (ci or 0)
                    + (config.bobChainLand or 0.1)
                    - side
            local function ci(hi)
                return hi > (config.bobChainExitMax or 40)
                    or hi > (config.bobChainExitShort or 10)
                        and hi / (config.burstMax or 28) > ui + (config.bobChainExitSlack or 0.3)
            end
            if not (circleExit and circleExit.chainAt == circleChain.chainAt and circleExit.started) then
                if ci(li + 1 - abs(Pi)) then
                    return nil
                end
            end
            circleExit = runtimeState.circleExit
            if not (circleExit and circleExit.chainAt == circleChain.chainAt) then
                circleExit = {
                    chainAt = circleChain.chainAt,
                    side = Pi >= 0 and 1 or -1,
                }
                runtimeState.circleExit = circleExit
            else
            end
            _i = config.burstMax or 28
            for index2 = 1, 2, 1 do
                side = index2 == 1 and circleExit.side or -circleExit.side
                index2, Si =
                    li + 1 - side * Pi,
                    Vector3.new(
                        circleChain.ox + WF * Di + Li * side * (li + 1),
                        vector.Y,
                        circleChain.oz + Qi * Di + WF * side * (li + 1)
                    )
                if
                    not (config.bobChainFarCheck ~= false and side * Pi < 0 and ci(index2))
                    and E(vector, Si)
                    and not (context.BB and context.BB.bobOrbPathSafe and not context.BB.bobOrbPathSafe(
                        vector,
                        Si,
                        _i
                    ))
                    and not (
                        context.BB
                        and context.BB.wallPathSafe
                        and not context.BB.wallPathSafe(vector, Si, _i, 0)
                    )
                then
                    circleExit.side = side
                    circleExit.started = true
                    return Si, index2, side
                end
            end
            return nil
        end
