                contextDangerAt(vector2.X, vector.Y, vector2.Z, WF, nil, nil, _i) > Oi
                or contextDangerAt(vector2.X, vector.Y, vector2.Z, (WF + Di) * 0.5, nil, nil, _i) > Oi
                or contextDangerAt(vector2.X, vector.Y, vector2.Z, Di, nil, nil, _i) > Oi
            then
                return false, "an attack there"
            end
            if WF > 0 then
                if context.BB and context.BB.pathBlocked and context.BB.pathBlocked(vector, vector2, Li) then
                    return false, "an attack in the way"
                end
                if
                    context.BB
                    and context.BB.bobOrbPathSafe
                    and not context.BB.bobOrbPathSafe(vector, vector2, Li)
                then
                    return false, "an orb in the way"
                end
                if not E(vector, vector2) then
