            if not WF and Oi.softUntil and now < Oi.softUntil then
                return nil
            end
            WF, Qi = N.X - vector.X, N.Z - vector.Z
            local _i, li, ci = sqrt(WF * WF + Qi * Qi), 0, 0
            if _i > 0.001 then
                li, ci = WF / _i, Qi / _i
            else
            end
            zF = math.max(zF or 16, 8)
            if _i >= 0.3 then
                if Oi.redTouch and Oi.redTouch(vector.X, vector.Z, N.X, N.Z) then
                    return nil
                end
                if Oi.inside and not Oi.inside(N, 0) then
                    if
