                        now < entry.landAt + 0.1
                        and (Qi - entry.p.X) ^ 2 + (Li - entry.p.Z) ^ 2 < (entry.r + N) ^ 2
                    then
                        return nil
                    end
                end
                if WF >= _i then
                    break
                end
                WF = math.min(WF + 1.5, _i)
            end
            Qi, Li = config.pkDashBody or 1.5, Pi
            for index2, entry2 in ipairs(Oi.circles or {}) do
                if now + Di < entry2.hitAt + 0.05 then
                    N = math.min(math.max(entry2.hitAt - now - Di, 0) * zF, _i)
                    index2, WF = vector.X + li * N, vector.Z + ci * N
                    Li = if (index2 - entry2.p.X) ^ 2 + (WF - entry2.p.Z) ^ 2 < (entry2.r + Qi) ^ 2
                        then Li + (config.pkCircleDmg or 350)
                        else Li
                else
                end
            end
            Qi = 0
            for index3, entry3 in ipairs(Oi.lanes or {}) do
                if now + Di < entry3.untilAt then
                    N = math.min(math.max(entry3.hitAt - now - Di, 0) * zF, _i)
