            contextReleaseMover(humanoid, zF)
            contextSetState(
                context.runComplete() and "run complete"
                    or ("no enemy in sight%s%s"):format(
                        runtimeState.wpIdleWhy and " - " .. runtimeState.wpIdleWhy or "",
                        hazardReader.bigRoom
                                and runtimeState.resetGate
                                and runtimeState.resetGate ~= "open"
                                and runtimeState.resetGate ~= "done"
                                and runtimeState.resetGate ~= "used"
                                and " [reset: " .. runtimeState.resetGate .. "]"
                            or ""
                    )
            )
        end
        if config.attackThread ~= false then
            task.spawn(function()
                while not (runtimeState and runtimeState.destroyed) do
                    task.wait(config.attackStep or 0.05)
                    pcall(function()
                        if
                            config.attackThread == false
                            or not runtimeState.farmEnabled
                            or runtimeState.modHalt
                        then
                            runtimeState.castReadyAt = nil
                            return
                        end
                        local aoeScanAt, coverFull = os.clock(), localPlayer.Character
                        local humanoid, l =
                            coverFull and (coverFull:FindFirstChildOfClass("Humanoid")),
                            coverFull and (coverFull:FindFirstChild("HumanoidRootPart"))
                        if not (humanoid and l and humanoid.Health > 0) then
                            runtimeState.castReadyAt = nil
                            return
                        end
                        if
                            not (
                                if context.readyDamageCasts and hazardReader.abilitySlots
                                    then (context.readyDamageCasts() or 0) >= 1
                                    else true
                            )
                        then
                            runtimeState.castReadyAt = nil
                            runtimeState.castAvailSince = nil
                            runtimeState.attackState = "on cooldown"
                            return
                        end
                        runtimeState.castAvailSince = runtimeState.castAvailSince or aoeScanAt
                        local position, u =
                            l.Position,
                            max(
                                context.fireReach and context.fireReach() or 0,
                                context.abilityReach and context.abilityReach() or 0,
                                config.abilityRangeKnown or 0,
                                config.castStartAt or 44
                            )
                        local h, m =
                            config.tagFirst ~= false and contextTagPending(position) > 0, combatBrain.target
                        if
                            not (
                                m
                                and not m.isBoss
                                and m.root
                                and m.root.Parent
                                and m.humanoid
                                and m.humanoid.Health > 0
                                and (m.x - position.X) ^ 2 + (m.z - position.Z) ^ 2 <= u * u
                                and not (h and contextMobTagged(m))
                            )
                        then
                            coverFull = nil
                            m = nil
                            for index, entry in ipairs(hazardReader.enemies or {}) do
                                if
                                    not entry.isBoss
                                    and entry.root
                                    and entry.root.Parent
                                    and entry.humanoid
                                    and entry.humanoid.Health > 0
                                    and (not h or contextMobUntagged(entry))
                                then
                                    local q, V = entry.x - position.X, entry.z - position.Z
                                    index = q * q + V * V
                                    if index <= u * u and (coverFull == nil or index < coverFull) then
                                        coverFull, m = index, entry
                                    else
                                    end
                                else
                                end
                            end
                        else
                        end
                        h = config.attackOverdueOn ~= false
                            and runtimeState.castAvailSince ~= nil
                            and aoeScanAt - runtimeState.castAvailSince > (config.attackOverdue or 1)
                        if not m and h then
                            coverFull = nil
                            for index2, entry2 in ipairs(hazardReader.enemies or {}) do
                                if
                                    not entry2.isBoss
                                    and entry2.root
                                    and entry2.root.Parent
                                    and entry2.humanoid
                                    and entry2.humanoid.Health > 0
                                then
                                    local S, q = entry2.x - position.X, entry2.z - position.Z
                                    index2 = S * S + q * q
                                    if index2 <= u * u and (coverFull == nil or index2 < coverFull) then
                                        coverFull, m = index2, entry2
                                    else
                                    end
                                else
                                end
                            end
                        else
                        end
                        if not m then
                            runtimeState.castReadyAt = nil
                            runtimeState.attackState = "ready, nothing in reach"
                            return
                        end
                        if aoeScanAt - (runtimeState.aoeScanAt or 0) >= (config.aoeScanEvery or 0.1) then
                            runtimeState.aoeScanAt = aoeScanAt
                            local coverFace, R, groupPlan = VF(position, config.drawAoeScan == true, h)
                            coverFull = (groupPlan or 0) > 0 and (R or 0) >= groupPlan
                            runtimeState.coverFace = coverFace
                            runtimeState.coverFull = coverFull
                            groupPlan = runtimeState.groupPlan
                            runtimeState.coverEnough = not (
                                    config.firstCastWholeStrict ~= false
                                    and groupPlan ~= nil
                                    and groupPlan.first == true
                                    and runtimeState.groupPlanAt ~= nil
                                    and aoeScanAt - runtimeState.groupPlanAt < 1
                                ) and (R or 0) >= (config.fireEnough or 3)
                            runtimeState.coverN = R or 0
                        end
                        runtimeState.attackState = ("%d in the disc%s"):format(
                            runtimeState.coverN or 0,
                            h and ", overdue" or ""
                        )
                        if
                            config.fireOnFullCover ~= false
                            and (runtimeState.coverFull or runtimeState.coverEnough)
                            and runtimeState.coverFace
                        then
                            if UF(humanoid, l, m, aoeScanAt, runtimeState.coverFace, h) then
                                runtimeState.castReadyAt = nil
                                runtimeState.coverFull = false
                                runtimeState.coverEnough = false
                            end
                            return
                        end
                        runtimeState.castReadyAt = runtimeState.castReadyAt or aoeScanAt
                        u = config.attackDeadline or 0.5
                        if config.firstHitWhole ~= false then
                            coverFull = runtimeState.groupPlan
                            u = if coverFull
                                    and coverFull.first
                                    and (coverFull.n or 0) > (coverFull.hereN or 0)
                                    and runtimeState.groupPlanAt
                                    and aoeScanAt - runtimeState.groupPlanAt < 0.5
                                then max(u, config.firstHitWindow or 3.5)
                                else u
                        else
                        end
                        runtimeState.attackState = ("%d in the disc, firing in %.1fs%s"):format(
                            runtimeState.coverN or 0,
                            math.max(u - (aoeScanAt - runtimeState.castReadyAt), 0),
                            runtimeState.skillGate and " (" .. tostring(runtimeState.skillGate) .. ")" or ""
                        )
                        if aoeScanAt - runtimeState.castReadyAt <= u then
                            return
                        end
                        if UF(humanoid, l, m, aoeScanAt, nil, h) then
                            runtimeState.castReadyAt = nil
                        end
                    end)
                end
            end)
        end
        context.MV, context.BR, context.brainTick, context.standoffFor, context.releaseMover, context.restoreWalkSpeed =
            movement, combatBrain, contextBrainTick, contextStandoffFor, contextReleaseMover, function(d)
                if d then
                    C(d, false)
                end
            end
    end

