            if runtimeState.destroyed or party.on ~= true or party.rejoin == false
                or type(j) ~= "table" or type(j.job) ~= "string" or j.job == "" or j.job == game.JobId then
                return false
            end
            if partyQueue.relayEnabled and not partyQueue.relayReady() then
