            end
            if partyQueue.relayAwaitRosterAck and partyQueue.relayAwaitRosterAck() then
                return false
            end
            local lateTarget = partyQueue.relayEnabled and partyQueue.relayLateJoinTarget(host, j)
            if
                (partyQueue.lastRunJob == nil or j.job ~= partyQueue.lastRunJob)
                and not (context.MD and context.MD.restRejoinOk and context.MD.restRejoinOk())
                and not lateTarget
            then
                return false
            end
            if j.over == true then
                return false
            end
            if not tonumber(j.at) or os.time() - tonumber(j.at) > 20 then
                return false
            end
            if partyQueue.rejoinJob ~= j.job then
                partyQueue.rejoinJob = j.job
                partyQueue.rejoinTries = 0
                partyQueue.rejoinSaid = nil
                partyQueue.rejoinAt = nil
            end
            if rejoinAt - (partyQueue.rejoinAt or -math.huge) < (config.afRejoinEvery or 20) then
                p(
                    ("%s is in a run - asked to join it (%s)"):format(
                        host,
                        tostring(partyQueue.rejoinSaid or "sending")
                    )
                )
                return true
            end
            if (partyQueue.rejoinTries or 0) >= (config.afRejoinMax or 8) then
                p(
                    ("%s is in a run - asked %d times, waiting for it to come back"):format(
                        host,
                        partyQueue.rejoinTries
                    )
                )
                return true
            end
            local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("remotes")
            local w = remotes and (remotes:FindFirstChild("sendJoinRequest"))
            if not (w and (w:IsA("RemoteFunction"))) then
                return false
            end
            partyQueue.rejoinAt, partyQueue.rejoinTries = rejoinAt, (partyQueue.rejoinTries or 0) + 1
            local try = partyQueue.rejoinTries
            local J = lateTarget and lateTarget.name or type(j.name) == "string" and j.name ~= "" and j.name or host
            local relayEpoch = partyQueue.relayEnabled and partyQueue.relay.snapshot.epoch
            local relayGeneration = partyQueue.relayEnabled and partyQueue.relay.generation
            local function stillCurrent()
                local active = partyQueue.load()
                if runtimeState.destroyed or active.on ~= true or active.rejoin == false then
                    return false
                end
                if not partyQueue.relayEnabled then
                    return true
                end
                if not partyQueue.relayReady() or partyQueue.relay.snapshot.epoch ~= relayEpoch
                    or partyQueue.relay.generation ~= relayGeneration
                    or partyQueue.relayAwaitRosterAck and partyQueue.relayAwaitRosterAck() then
                    return false
                end
                if lateTarget then
                    return partyQueue.relayLateJoinTarget(host, j) ~= nil
                end
                local current = partyQueue.presence(host, 20)
                return current ~= nil and current.job == j.job and current.over ~= true
                    and (current.place == "Level" or current.place == "100+")
            end
            task.spawn(function()
                if not stillCurrent() then
                    return
                end
                local success, Y, v, M = pcall(w.InvokeServer, w, J, false)
                if success and Y and M == true then
                    if not stillCurrent() then
                        return
                    end
                    success, Y, v = pcall(w.InvokeServer, w, J, true)
                else
                end
                if not stillCurrent() then
                    return
                end
                partyQueue.rejoinSaid = success and (Y and "request sent" or tostring(v or "refused"))
                    or "request failed"
                if context.queueLog then
                    context.queueLog("rejoin_request", {
                        host = host,
                        ok = tostring(success),
                        sent = tostring(Y),
                        msg = tostring(v),
                        force = tostring(M),
                        try = try,
                    })
                end
            end)
            p(("%s is in a run - asking to join it (try %d)"):format(host, try))
            return true
        end
        partyQueue.mates = function()
