                    wasRodin.maxGap = P
                end
                if P > 0.05 then
                    wasRodin.gap50 = wasRodin.gap50 + 1
                end
                if P > 0.1 then
                    wasRodin.gap100 = wasRodin.gap100 + 1
                    if P > 0.25 then
                        wasRodin.gap250 = wasRodin.gap250 + 1
                    end
                    local spikes = wasRodin.spikes
                    local h, m =
                        #spikes + 1, {
                            at = d - perf.since,
                            gap = P,
                            work = wasRodin.lastWork or 0,
                        }
                    m.state, spikes[h] = tostring(runtimeState.movementState or ""):sub(1, 70), m
                    if #spikes > 40 then
                        table.remove(spikes, 1)
                    end
                end
            else
            end
            local mainLoop = config.tickHz or 0
            if mainLoop > 0 then
                if runtimeState.lastTickAt and d - runtimeState.lastTickAt < 1 / mainLoop then
                    return
                end
                runtimeState.lastTickAt = d
            end
            O("reader", context.readerTick, d)
            O("lobby", context.lobbyTick, d)
            O("config", context.autosaveTick, d)
            O("range", context.judgeCasts, d)
            O("buffs", context.buffTick, d)
            O("brain", l, d)
            O("caster", context.casterTick, d)
            O("face", context.faceTick, d)
            runtimeState.econN = (runtimeState.econN or 0) + 1
            if
                not (
                    config.lowEndEconomy ~= false
                    and (runtimeState.tickMs or 0) > (config.lowEndLoad or 2)
                    and runtimeState.econN % 2 == 0
                )
            then
                O("draw", context.drawTick, d)
            end
            mainLoop = os.clock() - d
            if mainLoop > (runtimeState.stMax.mainLoop or 0) then
                runtimeState.stMax.mainLoop = mainLoop
            end
            runtimeState.tickMs = runtimeState.tickMs * 0.9 + (os.clock() - d) * 100
            if cur then
                local Q, work = os.clock() - d, cur.work
                work.n, work.sum = work.n + 1, work.sum + Q
                if Q > work.max then
                    work.max = Q
                end
                if Q > 0.008 then
                    work.over8 = work.over8 + 1
                end
                if Q > 0.016 then
                    work.over16 = work.over16 + 1
                end
                if Q > 0.033 then
                    work.over33 = work.over33 + 1
                end
                cur.frames.lastWork = Q
            end
        end)
    end

    return components
end)()

local context = {}
components.coreSettings(context)
context.loadConfig()
components.attackCatalog(context)
components.gearProfiles(context)
components.movementBoost(context)
components.hazardReader(context)
components.dangerGeometry(context)
components.odinMechanics(context)
components.bossPhases(context)
components.bubbleBoss(context)
components.movementCombat(context)
components.inventoryAutomation(context)
components.partyQueue(context)
components.raidAutomation(context)
components.uiLibrary(context)
components.drawing(context)
components.walls(context)
components.statisticsWebhooks(context)
components.interfaceMainLoop(context)

-- BEGIN EMBEDDED WORKSPACE SETTINGS
do
    local installWorkspaceSettings = (function()
-- Shared preferences only. Never synchronizes per-account holds, loot, or credentials.
return function(context, deps)
    deps=deps or {}
    local json=deps.json or game:GetService("HttpService")
    local read,write,exists=deps.read or readfile,deps.write or writefile,deps.exists or isfile
    local kind=deps.kind or typeof
    local fromHex=deps.fromHex or (Color3 and Color3.fromHex)
    local tasks=deps.tasks or task
    local cfg=context.CFG
    local active=true
    local groups={
        {path="HarvardLabs/configs/moddrop_shared.json",fields={
            modLeaveLegendary="boolean",modLeaveUltimate="boolean",modLeaveValT3="boolean",
            modLeaveEpic="boolean",modLeaveValAny="boolean",modWaitMin="wait",modWaitMax="wait",
            modLeaveGildenscaleT3="boolean",modLeaveGildenscaleAny="boolean",modLeaveEnhanced="boolean",
        }},
        {path="HarvardLabs/configs/visuals_shared.json",fields={
            renderOff="boolean",minimap="boolean",mapButton="boolean",mapAttackOneColor="boolean",
            mapAttackRainbow="boolean",mapAttackColor="color",attackRainbowAuto="boolean",
            mapKey="string",itemStatsAbbrev="boolean",upgradeCountAbbrev="boolean",itemGodpot="boolean",
            devVis="boolean",
        }},
    }
    local function localValue(key)
        if key=="devVis" then return context.devVisOn==true end
        local value=cfg[key]
        if kind(value)=="Color3" then return "#"..value:ToHex() end
        return value
    end
    local function capture(group)
        local values={}
        for key in pairs(group.fields) do values[key]={value=localValue(key)} end
        return values
    end
    local function valid(value,typ)
        if value==nil then return true end
        if typ=="wait" then return type(value)=="number" and value>=1 and value<=60 and value%1==0 end
        if typ=="color" then return type(value)=="string" and value:match("^#%x%x%x%x%x%x$")~=nil end
        if typ=="string" then return type(value)=="string" and #value<=40 end
        return type(value)==typ
    end
    local function report(group,message)
        if context.logT then context.logT("workspace-settings-"..group.path,15,"WorkspaceSettings",message..": "..group.path) end
    end
    local function readGroup(group)
        if type(read)~="function" then return nil,"unavailable" end
        if type(exists)=="function" then
            local ok,present=pcall(exists,group.path)
            if ok and not present then return nil,"missing" end
        end
        local ok,raw=pcall(read,group.path)
        if not ok or type(raw)~="string" and type(raw)~="table" then return nil,"unavailable" end
        local decoded,value=pcall(function()return json:JSONDecode(raw)end)
        if not decoded or type(value)~="table" or value.v~=1 or type(value.values)~="table" then return nil,"invalid" end
        for key,typ in pairs(group.fields)do
            local entry=value.values[key]
            if entry~=nil and (type(entry)~="table" or not valid(entry.value,typ)) then return nil,"invalid" end
        end
        return value.values
    end
    local function writeGroup(group,values)
        if type(write)~="function" then return false end
        if context.ensureFolders then pcall(context.ensureFolders) end
        local ok,result=pcall(function()return write(group.path,json:JSONEncode({v=1,values=values}))end)
        if not ok or result==false then report(group,"Could not save shared preferences");return false end
        return true
    end
    local function refresh(changed)
        if changed.devVis and context.devVis then pcall(context.devVis,changed.devVis.value==true) end
        if changed.renderOff then
            if context.applyRender then pcall(context.applyRender,true) end
            if context.MM and context.MM.onUltimate then pcall(context.MM.onUltimate,cfg.renderOff==true) end
        end
        if changed.minimap or changed.mapButton then
            if context.MM and context.MM.apply then pcall(context.MM.apply) end
        end
        if changed.itemGodpot and cfg.itemGodpot~=true and context.gpHide then pcall(context.gpHide) end
        if context.saveConfig then pcall(context.saveConfig) end
        if context.refreshAllWidgets then pcall(context.refreshAllWidgets) end
    end
    local function syncGroup(group)
        local current=capture(group)
        group.last=group.last or current
        local remote,status=readGroup(group)
        if not remote and status~="missing" then
            report(group,"Shared preferences unavailable or malformed; keeping local settings")
            return
        end
        local merged,writeNeeded={},remote==nil
        for key in pairs(group.fields)do
            local dirty=current[key].value~=group.last[key].value
            if not remote or not remote[key] or dirty then
                merged[key]=current[key]
                writeNeeded=true
            else
                merged[key]={value=remote[key].value}
            end
        end
        -- Only acknowledge local edits after a successful write, so failed writes retry.
        if writeNeeded and not writeGroup(group,merged) then return end
        local changed={}
        for key,typ in pairs(group.fields)do
            local value=merged[key].value
            if value~=current[key].value then
                if key=="devVis" then changed[key]={value=value}
                elseif typ=="color" and value~=nil then
                    local ok,color=pcall(fromHex,value)
                    if ok then cfg[key]=color;changed[key]={value=value} end
                else cfg[key]=value;changed[key]={value=value} end
            end
        end
        if next(changed)then refresh(changed)end
        group.last=capture(group)
    end
    local lastFps
    local handle={}
    handle.tick=function()
        if not active or context.RT.destroyed then return end
        for _,group in ipairs(groups)do syncGroup(group)end
        -- HUD/FPS already have their own shared file; refresh their widgets live.
        if context.fpsShared then
            local ok,raw=pcall(function()
                local fps=context.fpsShared()
                return table.concat({tostring(fps.hud),tostring(fps.cap),tostring(fps.carry),tostring(fps.leech),tostring(fps.uncap)},"|")
            end)
            if ok and raw~=lastFps then
                lastFps=raw
                if context.refreshAllWidgets then pcall(context.refreshAllWidgets)end
            end
        end
    end
    handle.stop=function()
        active=false
        if handle.thread and tasks then pcall(tasks.cancel,handle.thread);handle.thread=nil end
    end
    context.workspaceSettingsSync=handle
    -- Initialize the local baseline before adopting existing shared preferences.
    for _,group in ipairs(groups)do group.last=capture(group)end
    handle.tick()
    if deps.start~=false and tasks then
        handle.thread=tasks.spawn(function()
            while active and not context.RT.destroyed do
                tasks.wait(1)
                if active and not context.RT.destroyed then handle.tick()end
            end
        end)
    end
    return handle
end
    end)()
    installWorkspaceSettings(context)
end
-- END EMBEDDED WORKSPACE SETTINGS

-- BEGIN EXPERIMENTAL DUNGEON PROGRESSION
(function()
-- Experimental end-of-run progression. Does not change the party's saved map.
return function(context, deps)
    deps = deps or {}
    local queue = context.AF
    local pendingDeparture
    local players = deps.players or game:GetService("Players")
    local workspace = deps.workspace or game:GetService("Workspace")
    local function localLevel(name)
        for _, player in ipairs(players:GetPlayers()) do
            if string.lower(player.Name) == string.lower(name) then
                local stats = player:FindFirstChild("leaderstats")
                local level = stats and stats:FindFirstChild("Level")
                return level and tonumber(level.Value)
            end
        end
    end
    queue.progressionCheck = function()
        local cfg = queue.autoDungeonConfig(queue.load())
        if cfg.on ~= true or cfg.auto == false or not queue.role() then return nil end
        if queue.relayEnabled and (not queue.relayReady() or queue.relayAwaitRosterAck()) then return nil end
        local lowest, count = nil, 0
        for _, account in ipairs(cfg.accounts or {}) do
            if account.enabled ~= false then
                count += 1
                local level = localLevel(account.name)
                if not level or level <= 0 then
                    local presence = queue.presence(account.name, 20)
                    level = presence and tonumber(presence.level)
                end
                if not level or level <= 0 then return nil, "missing fresh level: " .. account.name end
                lowest = math.min(lowest or level, level)
            end
        end
        if count == 0 then return nil end
        local target, difficulty, required = queue.bestFor(lowest, cfg.hardest, cfg.start)
        if not target or not required or required > lowest then return nil end
        local name = workspace:FindFirstChild("dungeonName")
        local current = name and tostring(name.Value)
        if not current or current == "" then return nil end
        local levels = queue.LEVELS[current]
        if not levels then return nil end -- Event/unknown maps have no verified level ordering.
        local currentDifficulty = context.WH and context.WH.liveDifficulty and context.WH.liveDifficulty()
        if currentDifficulty then currentDifficulty = currentDifficulty:gsub(" %(Hardcore%)", "") end
        local currentRequired
        for diff, level in pairs(levels) do
            if currentDifficulty and string.lower(diff) == string.lower(currentDifficulty) then currentRequired = level; break end
        end
        if not currentRequired then
            -- Unknown difficulty: only advance past the entire current map.
            if target == current then return nil end
            currentRequired = 0
            for _, level in pairs(levels) do currentRequired = math.max(currentRequired, level) end
        end
        if required <= currentRequired or (target == current and difficulty == currentDifficulty) then return nil end
        return {map=target, difficulty=difficulty, required=required, lowest=lowest}
    end
    queue.progressionTick = function(now)
        if context.RT.destroyed then return false end
        local cfg = queue.autoDungeonConfig(queue.load())
        if cfg.on ~= true or cfg.auto == false or not queue.role() then return false end
        local lb = context.LB
        if not lb or not lb.runOverAt then return false end
        if context.MD and (context.MD.halted or context.MD.pendingDrop or context.MD.pendingBreak) then return false end
        local settle = math.max(5, tonumber(context.CFG.afReplaySettle) or 5)
        if now - lb.runOverAt < settle then
            lb.status = "run finished; checking party levels before replay"
            return true
        end
        local target = pendingDeparture or queue.progressionCheck()
        if not target then return false end
        lb.afMoveOn = target.map .. " " .. target.difficulty
        if context.WH and context.WH.pendingUntil and now < context.WH.pendingUntil then
            lb.status = "party ready for " .. lb.afMoveOn .. "; waiting for the win post"
            return true
        end
        lb.status = "party ready for " .. lb.afMoveOn .. "; back to the lobby"
        pendingDeparture = target -- A stale heartbeat during teleport must not restart replay.
        -- Every member makes the same check and leaves independently. No shared file
        -- signal, no disabling the party, and no reliance on afCarryLeave/replay.
        queue.leaveGo(now, "Party levels unlocked " .. lb.afMoveOn)
        return true
    end
end

end)()(context)
-- END EXPERIMENTAL DUNGEON PROGRESSION
return context
